insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('dea-gschraufde-do-vuan-im-aunzug-reed-ois-waarada-beim-oopanboi', 'Dea Gschraufde do vuan im Aunzug reed, ois waarada beim Oopanboi!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Geschraubte da vorn im Anzug redet, als wär er beim Opernball!', '[{"kategorie": "wörtlich", "text": "\"Der hochgestochene Lackaffe da vorn im Anzug redet, als wär er beim Opernball!\"  2. Der Hochgestochene da vorn im Zwirn doziert, als säße er in der Loge der Wiener Staatsoper!  3. Der aufgeplusterte Anzughengst da vorn schwadroniert, als wär’s ''ne kaiserliche Hofansprache!"}]'::jsonb, ''),
  ('ziag-liawa-de-gschraufdn-au-waeu-da-plotz-is-a-aanziga-ocka', 'Ziag liawa de Gschraufdn au, wäu da Plotz is a aanziga Ocka!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Zieh lieber die Geschraubten an, weil der Platz ist ein einziger Acker!', '[{"kategorie": "wörtlich", "text": "\"Zieh lieber die Schraubstollenschuhe an, denn der Platz ist ein einziger Acker!\"  2. Nimm lieber die Langstoller  – der Platz ist ein Sumpf, kein Spielfeld!  3. Mit Nocken bist du heut chancenlos – Geschraubte oder gar nicht!"}]'::jsonb, ''),
  ('reed-ned-so-gschraufd-dahea', 'Reed ned so gschraufd dahea!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Rede nicht so geschraubt daher!', '[{"kategorie": "wörtlich", "text": "\"Red nicht so hochgestochen daher!\"  2. \"Sprich nicht so übertrieben gewählt!\"  3. \"Drücke dich nicht so gestelzt aus!\"  4. Sprich nicht so gekünstelt – red normal!"}]'::jsonb, ''),
  ('de-brood-san-schoo-featig-gschmiiad', 'De Brood san schoo featig gschmiiad!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Brote sind schon fertig geschmiert!', '[{"kategorie": "wörtlich", "text": "\"Die Brote sind schon fertig bestrichen!\"  2. Die Brote sind schon mit Liebe eingeschmiert!  3. Die belegten Brote sind bereits angerichtet!"}]'::jsonb, ''),
  ('guad-gschmiiad-is-hoib-regiiad', 'Guad gschmiiad is hoib regiiad!', '', '', '', 'Wiener Gaunersprache', 'Gut geschmiert ist halb regiert!', '[{"kategorie": "wörtlich", "text": "\"Wer schmiert, regiert!\"  2. Geschmiert regiert sich’s leichter!  3. Mit dem richtigen Schmiergeld läuft der Laden wie geschmiert!"}]'::jsonb, ''),
  ('wem-waachschmiian', 'wem waachschmiian', '', '', '', 'Wiener Gaunersprache', 'jemanden weichschmieren', '[{"kategorie": "wörtlich", "text": "\"jemanden weichschmieren\" (Kompositum aus \"weich\"=\"gefügig\" und \"schmieren\"=\"bestechen\")"}, {"kategorie": "Gaunersprache", "text": "\"jemanden durch Zahlung von Schmiergeld gefügig machen\", \"jemanden mit Scheinchen weichkochen\", jemanden bestechen, \"schmieren\", korrumpieren"}]'::jsonb, 'Den hauma waachgschmiiad - jetzt taunzda noch unsara Pfeifn!'),
  ('den-hauma-waachgschmiiad-jetzt-taunzda-noch-unsara-pfeifn', 'Den hauma waachgschmiiad - jetzt taunzda noch unsara Pfeifn!', '', '', '', 'Wiener Gaunersprache', 'Den haben wir weichgeschmiert - jetzt tanzt er nach unserer Pfeife!', '[{"kategorie": "wörtlich", "text": "\"Den haben wir mit Scheinchen weichgekocht - jetzt tanzt er nach unserer Pfeife!\"  2. Den haben wir auf Linie geschmiert – jetzt gehorcht er wie ein Schoßhündchen!  3. Den haben wir mit Bargeld weichgedampft  – jetzt spurt er wie ein Dressurpferd!"}]'::jsonb, 'wem waachschmiian'),
  ('da-gschmiiade-hod-ollas-duachgwunkn-dea-taunzd-wia-wia-pfeifn', 'Da Gschmiiade hod ollas duachgwunkn - dea taunzd, wia wia pfeifn!', '', '', '', 'Wiener Gaunersprache', 'Der Geschmierte hat alles durchgewunken - der tanzt, wie wir pfeifen!', '[{"kategorie": "wörtlich", "text": "\"Der Geschmierte hat alles abgenickt - der tanzt jetzt nach unserer Pfeife!\"  2. Der Schmierling hat alles genehmigt - der spurt wie ein Dressurpferd!  3. Unser Schmiergeldpilot hat alles durchgewunken und dann schön Männchen gemacht!"}]'::jsonb, ''),
  ('moch-da-kaan-stress-de-gschmiiadn-schdeengan-olle-auf-unsara-gehoidslistn', 'Moch da kaan Stress - de Gschmiiadn schdeengan olle auf unsara Gehoidslistn!', '', '', '', 'Wiener Gaunersprache', 'Mach dir keinen Stress - die Geschmierten stehen alle auf unserer Gehaltsliste!', '[{"kategorie": "wörtlich", "text": "\"Mach dir keinen Stress - die [[Polypen]] stehen alle auf unserer Gehaltsliste!\"  2. Alles easy – die [[Spinaderer]] haben wir alle eingekauft, die kriegen ihr Schweigegeld regelmäßig!  3. Mach dir keinen Kopf – die Sheriffs sind sauber geschmiert und tanzen alle nach unserer Pfeife!"}]'::jsonb, ''),
  ('mei-groossvooda-hods-grissbaamkreiz-no-soeoewa-zsaummzimmad-und-es-hoid-bis-heit', 'Mei Groossvooda hods Grissbaamkreiz no sööwa zsaummzimmad - und es hoid bis heit!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mein Großvater hat das Christbaumkreuz noch selbst zusammengezimmert – und es hält bis heute!', '[{"kategorie": "wörtlich", "text": "\"Das Christbaumkreuz ist ein Werk meines Großvaters – er hat es eigenhändig gebaut, und es hält bis heute!\"  2. Mein Opa hat den Weihnachtsbaumständer einst selbst gezimmert – und dieser trägt bis heute Jahr für Jahr den Baum!  3. Mein Opa hat das Christbaumkreuz damals noch selbst zusammengehämmert – und das Ding steht steht heute noch wie am ersten Tag!"}]'::jsonb, ''),
  ('de-kinda-haum-de-grooshupfa-in-an-glaasl-gsaummaed-und-daunn-de-mama-damit-gschreckd', 'De Kinda haum de Grooshupfa in an Glaasl gsaummäd und daunn de Mama damit gschreckd!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Die Kinder haben die Grashüpfer in einem Glas gesammelt und dann die Mama damit erschreckt!', '[{"kategorie": "wörtlich", "text": "\"Die Kinder sammelten Grashüpfer in einem Glas und erschreckten damit dann ihre Mutter!\"  2. Die Kids haben Grashüpfer in ein Glas gestopft und sind damit auf Mama los – die hat sich schön erschreckt!  3. Die kleinen Racker haben Grashüpfer gesammelt und ihrer Mama damit fast einen Herzinfarkt beschert!"}]'::jsonb, ''),
  ('waunn-da-grooshupfa-in-unsan-teich-amoi-losquaakd-heada-de-gaunze-nocht-nimma-auf', 'Waunn da Grooshupfa in unsan Teich amoi losquaakd, heada de gaunze Nocht nimma auf!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Wenn der Grashüpfer in unserem Teich einmal losquakt, hört er die ganze Nacht nicht mehr auf!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Laubfrosch in unserem Teich einmal losquakt, hört er die ganze Nacht nicht mehr auf!\"  2. Fängt der Laubfrosch in unserem Teich erst mal an zu quaken, ist an Schlaf nicht mehr zu denken!  3. Kaum stimmt der Laubfrosch sein Gequake an, wird die Nacht zur Frosch-Oper – ohne Pause, ohne Gnade!"}]'::jsonb, ''),
  ('ea-is-no-a-grooshupfa-owa-a-aufgweckda-dea-mochd-beschdimmd-sein-weeg', 'Ea is no a Grooshupfa, owa a aufgweckda - dea mochd beschdimmd sein Weeg!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Er ist noch ein Grashüpfer, aber ein aufgeweckter – der macht bestimmt seinen Weg!', '[{"kategorie": "wörtlich", "text": "\"Er ist noch ein Frischling, aber ein kluger Kopf – der macht bestimmt seinen Weg!\"  2. Er ist zwar noch jung, aber ziemlich pfiffig – der wird’s bestimmt weit bringen!  3. Er ist zwar noch ein Greenhorn, aber nicht auf den Kopf gefallen – der macht seinen Weg!"}]'::jsonb, ''),
  ('waunn-in-wien-de-sunn-untageed-kumman-im-prooda-ned-nua-de-goeoesn-ausse-sondan-aa-de-grosshupfa-in-eanare-schdecklschuach', 'Waunn in Wien de Sunn untageed, kumman im Prooda ned nua de Göösn ausse, sondan aa de Grosshupfa in eanare Schdecklschuach!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wenn in Wien die Sonne untergeht, kommen im Prater nicht nur die Gelsen raus, sondern auch die Grashüpfer in ihren Stöckelschuhen!', '[{"kategorie": "wörtlich", "text": "\"Wenn in Wien die Sonne untergeht, kommen im Prater nicht nur die Mücken raus, sondern auch die Strichmädchen in ihren High Heels!\"  2. Wenn die Dämmerung über Wien hereinbricht, tauchen im Prater neben den Stechmücken auch die Strichmädchen in High Heels auf, die im Grünen auf einen Stecher warten!  3. Im Prater kommen abends zwei Arten von Grashüpfern raus: die einen, die stechen – und die anderen, die sich für Geld stechen lassen!"}]'::jsonb, ''),
  ('dea-hod-an-uandlichn-gooda-auf-dem-kennta-glott-sei-bia-ooschdoeoen', 'Dea hod an uandlichn Gooda - auf dem kennta glott sei Bia ooschdöön!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat einen ordentlichen Goder - auf dem könnte er glatt sein Bier abstellen!', '[{"kategorie": "wörtlich", "text": "\"Der hat ein ordentliches Doppelkinn - auf dem könnte er glatt sein Bier abstellen!\"  2. Wenn der seinen Kopf hebt, hängt sein Doppelkinn raus wie ein kleiner Biertisch!  3. Auf der riesigen Speckfalte unter seinem Kinn könnte man glatt ein Glas Bier abstellen!"}]'::jsonb, ''),
  ('des-goeoedal-is-a-fetta-bissn-wiad-bei-uns-greichad-und-geed-daunn-in-de-presswuaschd', 'Des Göödal is a fetta Bissn - wiad bei uns greichad und geed daunn in de Presswuaschd!', '', '', '', 'Wiener Fleischhauer-Slang', 'Das Göderl is ein fetter Bissen – wird bei uns geräuchert und geht dann in die Presswurst!', '[{"kategorie": "wörtlich", "text": "\"Das Fleischstück zwischen Rüssel und Brust des Schweins is ein fetter Bissen – es wird bei uns geräuchert und geht dann in die Presswurst!\"  2. Fettgewebe aus dem Schweinehals – wird bei uns traditionell geselcht und zur Herstellung von Presswurst verwendet!  3. Das gut durchzogene Stück vom Kinnbereich des Schweins wird bei uns geräuchert und in die Presswurst eingearbeitet!"}]'::jsonb, ''),
  ('wems-goodal-krauln', 'wems Goodal krauln', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem das Goderl kraulen', '[{"kategorie": "wörtlich", "text": "\"jemandem das Doppelkinn kraulen\""}, {"kategorie": "fig.", "text": "\"jemanden durch zärtliches Massieren dessen Doppelkinns besänftigen\""}, {"kategorie": "scherzhaft für", "text": "\"jemandem Honig ums Maul schmieren\""}, {"kategorie": "", "text": "jemandem schöntun"}, {"kategorie": "", "text": "sich bei jemandem einschmeicheln"}, {"kategorie": "", "text": "sich bei jemandem Liebkind machen"}]'::jsonb, 'Waunns noch dera geed, kraulds an jeedn es Goodal, dea wos a goidane Tiaschnoin hod!'),
  ('waunns-noch-dera-geed-kraulds-an-jeedn-es-goodal-dea-wos-a-goidane-tiaschnoin-hod', 'Waunns noch dera geed, kraulds an jeedn es Goodal, dea wos a goidane Tiaschnoin hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wenn’s nach ihr geht, krault sie jedem das Goderl, der eine goldene Türschnalle hat!', '[{"kategorie": "wörtlich", "text": "\"Wenn’s nach ihr geht, krault sie jedem Mann das Doppelkinn, wenn sie eine goldene Türschnalle sieht!\"  2. Die schleimt sich bei jedem Mann ein, wenn sein Türschnallerl nach Gold ausschaut!  3. Ihre Finger finden jedes Goderl, wo ein goldener Türgriff glänzt!"}]'::jsonb, 'wems Goodal krauln'),
  ('wems-goodal-krotzn', 'wems Goodal krotzn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem das Goderl kratzen', '[{"kategorie": "wörtlich", "text": "\"jemandem das Doppelkinn kratzen\""}, {"kategorie": "fig.", "text": "\"jemanden durch zärtliches Massieren dessen Doppelkinns besänftigen\""}, {"kategorie": "scherzhaft für", "text": "\"jemandem Honig ums Maul schmieren\""}, {"kategorie": "", "text": "jemandem schöntun"}, {"kategorie": "", "text": "sich bei jemandem einschmeicheln"}, {"kategorie": "", "text": "sich bei jemandem Liebkind machen"}]'::jsonb, 'Imma dessöwe mit dem Hiani - zeaschd hängda ma a Goschn au und dann tuada ma es Goodal krotzn!'),
  ('imma-dessoewe-mit-dem-hiani-zeaschd-haengda-ma-a-goschn-au-und-dann-tuada-ma-es-goodal-krotzn', 'Imma dessöwe mit dem Hiani - zeaschd hängda ma a Goschn au und dann tuada ma es Goodal krotzn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Immer dasselbe mit diesem Hirni - zuerst hängt er mir eine Goschn an und dann kratzt er mir das Goderl!', '[{"kategorie": "wörtlich", "text": "\"Immer dasselbe mit diesem Hirnschüssler - zuerst schimpft er mich ordinär und dann kommt er sich bei mir einschleimen!\"  2. Immer dasselbe Theater mit dem Deppen - zuerst beschimpft er mich wie ein Fischweib – und fünf Minuten später schmiert er mir wieder Honig ums Maul!  3. Immer wieder dasselbe Spiel mit diesem Trottel - zuerst fährt er mich an wie eine wildgewordene Gelsen und kurz später kommt er angekrochen ein wie a streichelbedürftiger Kater auf Schmusekurs!"}]'::jsonb, 'wems Goodal krotzn'),
  ('wem-ums-goodal-gee', 'wem ums Goodal gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem ums Goderl gehen', '[{"kategorie": "wörtlich", "text": "\"jemandem ans Doppelkinn gehen\""}, {"kategorie": "fig.", "text": "\"jemanden durch zärtliches Massieren dessen Doppelkinns besänftigen\""}, {"kategorie": "scherzhaft für", "text": "\"jemandem Honig ums Maul schmieren\""}, {"kategorie": "", "text": "jemandem schöntun"}, {"kategorie": "", "text": "sich bei jemandem einschmeicheln"}, {"kategorie": "", "text": "sich bei jemandem Liebkind machen"}]'::jsonb, 'Si is eam so laung ums Goodal gaungan, bisas gheirad hod!'),
  ('si-is-eam-so-laung-ums-goodal-gaungan-bisas-gheirad-hod', 'Si is eam so laung ums Goodal gaungan, bisas gheirad hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie ist ihm so lange ans Goderl gegangen, bis er sie geheiratet hat!', '[{"kategorie": "wörtlich", "text": "\"Sie hat sein Doppelkinn so lange massiert, bis er sie geheiratet hat!\"  2. Sie hat sich bei ihm so lange eingeschleimt, bis er sie geheiratet hat!  3. Die hat ihm so lange Honig ums Maul geschmiert, bis er sie blind zum Traualtar geführt hat!"}]'::jsonb, 'wem ums Goodal gee'),
  ('friara-woa-bei-d-gschroppn-de-untagattn-glei-ins-hemad-eignaad', 'Friara woa bei d''Gschroppn de Untagattn glei ins Hemad eignaad!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher war bei den Gschroppen die Untergatten gleich ins Hemd eingenäht!', '[{"kategorie": "wörtlich", "text": "\"Früher war bei den Kindern die Unterhose gleich ins Hemd eingenäht!\"  2. Früher hat man den Kindern das Hemd gleich an die Unterhose drangenäht – so ist nichts verrutscht und im Winter war ihnen nicht mehr so kalt!  3. Damit nix verrutscht und die Kleinen nicht frieren, hat man ihnen früher Hose und Hemd einfach zu einem Einteiler zusammengenäht!"}]'::jsonb, ''),
  ('eignaad-is-eignaad-und-wiad-nimma-zruckgeem', 'Eignaad is eignaad und wiad nimma zruckgeem!', '', '', '', 'Wiener Gaunersprache', 'Eingenäht ist eingenäht und wird nicht mehr zurückgegeben!', '[{"kategorie": "wörtlich", "text": "\"Geklaut bleibt geklaut und wird nicht mehr zurückgegeben!\"  2. Was weg ist, ist weg – und wird nicht wieder hergegeben!  3. Was man klaut, behält man – Rückgaberecht gibt’s nur im Möbelhaus!"}]'::jsonb, ''),
  ('eignaad-sei', 'eignaad sei', '', '', '', 'Wiener Gaunersprache', 'eingenäht sein', '[{"kategorie": "", "text": "im Gefängnis sitzen"}, {"kategorie": "", "text": "hinter schwedischen Gardinen dunsten"}, {"kategorie": "", "text": "[[auf]] Hääfnualaub sei"}]'::jsonb, 'Ea woa zwa Joa eignaad, owa jetzt isa wieda auf da Pistn!'),
  ('ea-woa-zwa-joa-eignaad-owa-jetzt-isa-wieda-auf-da-pistn', 'Ea woa zwa Joa eignaad, owa jetzt isa wieda auf da Pistn!', '', '', '', 'Wiener Gaunersprache', 'Er war zwei Jahre eingenäht, aber jetzt ist er wieder auf der Piste!', '[{"kategorie": "wörtlich", "text": "\"Er war zwei Jahre lang im Gefängnis, aber jetzt ist er wieder auf der Piste!\"  2. Er ist zwei Jahre im Bau gesessen, aber jetzt dreht er draußen wieder munter seine Runden!  3. Zwei Jahre hat er den Knast von innen gesehen – jetzt schnuppert er wieder Straßenluft!  4. Zwei Jahre Zelle, aber jetzt ist er wieder auf Achse – und voll im Geschäft!"}]'::jsonb, 'eignaad sei'),
  ('i-tschuk-da-glei-aane-aufrs-guck-waunnsd-deppad-bist', 'I tschuk da glei aane aufrs Guck, waunnsd deppad bist!', '', '', '', 'Wiener Gaunersprache', 'Ich tschuck dir gleich eine aufs Guck, wenn du deppert bist!', '[{"kategorie": "wörtlich", "text": "\"Ich schlage dir gleich aufs Auge, wenn du deppert bist!\"  2. Pass auf, sonst fängst du dir gleich blitzartig eine Augenwatschn ein!  3. Noch ein blöder Spruch und ich pflanz ich dir ''ne Faust ins Gesicht – blitzartig und  gratis!"}]'::jsonb, ''),
  ('tschuk-aufs-guck', 'Tschuk aufs Guck', '', '', '', 'Wiener Gaunersprache', 'Tschuck aufs Guck', '[{"kategorie": "wörtlich", "text": "\"kurzer, gezielter Schlag aufs Auge\""}, {"kategorie": "allg.", "text": "blitzartiger Schlag aufs Auge"}, {"kategorie": "", "text": "\"Augenschwinger\""}]'::jsonb, ''),
  ('wueuesd-an-tschuk-aufs-guck', 'Wüüsd an Tschuk aufs Guck?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Willst du einen Tschuck aufs Guck?', '[{"kategorie": "wörtlich", "text": "\"Willst du einen Blitzschwinger aufs Auge?\"  2. Soll ich dir ein blaues Auge schlagen?  3. Soll ich dir einen gezielten Faustschlag aufs Auge verpassen?"}]'::jsonb, 'Tschuk aufs Guck'),
  ('waunns-gickal-nua-gackad-und-ned-kraad-foeoen-eam-entweda-da-mut-oda-de-eia', 'Waunns Gickal nua gackad und ned kraad, föön eam entweda da Mut oda de Eia!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn s''Gickerl nur gackert und nicht kräht, fehlen ihm entweder der Mut oder die Eier!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Haushahn nur gackert und nicht kräht, fehlen ihm entweder der Mut oder die Eier!\"  2. Wenn der Hahn nur gackert und nicht kräht, hat er entweder keine Stimme oder keine Eier!  3. (fig.) Wer nur gackert, aber nicht kräht, hat vielleicht das Amt, aber nicht das Format!"}]'::jsonb, ''),
  ('bevua-dea-giaral-a-rundn-zoid-gfriad-de-hoeoe', 'Bevua dea Giaral a Rundn zoid, gfriad de Höö!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Bevor dieser Gieral eine Runde bezahlt, gefriert die Hölle!', '[{"kategorie": "wörtlich", "text": "\"Bevor dieser Geizkragen eine Runde bezahlt, gefriert die Hölle!\"  2. Bevor der die Geldbörse zuckt, sind wir bestimmt schon alle tot!  3. Bevor der eine Runde spendiert, kannst gleich auf ein Wunder warten!"}]'::jsonb, ''),
  ('dea-giaral-hod-beim-bueffaeae-ned-amoi-luft-ghoid-nur-gschaufaed', 'Dea Giaral hod beim Büffää ned amoi Luft ghoid – nur gschaufäd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Gieral hat beim Buffet nicht einmal Luft geholt – nur geschaufelt!', '[{"kategorie": "wörtlich", "text": "\"Der Fresssack hat beim Buffet nicht einmal Luft geholt – nur geschaufelt!\"  2. Der gierige Vielfraß hat das Buffet leergeräumt wie ein Schneepflug im Jänner!  3. Der Gierrammel hat alles vom Buffet weggesaugt - wie ein Staubsauger im Fressrausch!"}]'::jsonb, ''),
  ('a-giarammae-und-a-millionaea-kenntn-zwueuelling-sei-owa-nua-aana-von-de-zwaa-gibds-zua', 'A Giarammä und a Millionäa kenntn Zwüülling sei - owa nua aana von de zwaa gibds zua!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Gierrammel und ein Millionär könnten Zwillinge sein – aber nur einer von beiden gibt es zu!', '[{"kategorie": "wörtlich", "text": "\"Ein Geizkragen und ein Millionär könnten Zwillinge sein – aber nur einer von beiden gibt es zu\""}, {"kategorie": "", "text": "Ein Geizkragen und ein Millionär sind wie Brüder – nur dass der eine besser lügen kann!  3. Der Geizige spart aus Angst, der Millionär aus Kalkül – das Ergebnis bleibt dasselbe: nix übrig für andere!"}]'::jsonb, ''),
  ('dea-typ-is-so-a-giarammae-dea-frissd-sogoa-in-toella-mit-waunnsd-ned-aufpassd', 'Dea Typ is so a Giarammä - dea frissd sogoa in Tölla mit, waunnsd ned aufpassd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Typ ist so ein Gierrammel - der frisst sogar den Teller mit, wenn du nicht aufpasst!', '[{"kategorie": "wörtlich", "text": "\"Der Typ ist ein derart gieriger Fresssack - der würde sogar den Teller mitessen, wenn du nicht aufpasst!\"  2. Der Typ ist ein Vielfraß wie aus’m Bilderbuch – der frisst dir Teller und Serviette gleich mit, wenn du nicht achtgibst!  3. Der Typ ist so verfressen, bei dem ist nicht einmal das Porzellan sicher!"}]'::jsonb, ''),
  ('a-ochtl-mit-giss', 'A Ochtl mit Giss!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Ein Achtel mit Gießhübler Wasser', '[{"kategorie": "hist., wörtlich", "text": "Ein Achtel Wein, gestreckt mit einem Achtel Gießhübler Wasser (Gießhübler Wasser“ war im 18. und 19. Jahrhundert ein bekanntes, kohlensäurehaltiges Mineral- und Heilwasser aus dem böhmischen Ort Gießhübel bei Karlsbad. Es galt als wohltuend für Verdauung und Stoffwechsel, wurde international exportiert und war ein Symbol bürgerlicher Kur- und Trinkkultur. Sein Erb lebt in der Marke Mattoni bis heute weiter)"}, {"kategorie": "", "text": "Ein Achtel Wein gespritzt auf ein Viertel!  3. Ein Vierterl Spritzwein!"}]'::jsonb, ''),
  ('de-giarichn-bonzn-schdopfn-si-de-toschn-voi-und-wia-klaane-leit-kennan-uns-boid-ka-eitriche-beim-wiaschdla-mea-leistn', 'De giarichn Bonzn schdopfn si de Toschn voi, und wia klaane Leit kennan uns boid ka Eitriche beim Wiaschdla mea leistn!', '', '', '', 'Wiener Würstelstandjargon', 'Die gierigen Bonzen stopfen sich die Taschen voll, und wir kleinen Leute können uns bald keine Eitrige mehr beim Würschtler leisten!', '[{"kategorie": "wörtlich", "text": "\"Die raffgierigen Manager stopfen sich die Taschen voll, und wir, die kleinen Leute, werden uns bald keine Käsekrainer mehr beim Würstelstand leisten können!\"  2. Die Gierschlucker in der Chefetage fressen sich fett an ihren Boni, und wir werden uns bald nicht einmal mehr a eine g’scheite Käsekrainer leisten können!  3. Die raffgierigen Manager kassieren unverschämte Gehälter, während der einfache Bürger bald auf seinen Würstelstand verzichten muss!"}]'::jsonb, ''),
  ('so-giarich-wia-dea-issd-kennt-ma-maana-ea-hod-in-kriag-iwaleebd-und-frissd-jetzt-auf-vuaroot', 'So giarich wia dea issd, kennt ma maana, ea hod in Kriag iwaleebd und frissd jetzt auf Vuaroot!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'So gierig wie der isst, könnte man meinen, er hat den Krieg überlebt und frisst jetzt auf Vorrat!', '[{"kategorie": "wörtlich", "text": "\"So gierig wie der isst, könnte man meinen, er ist im Krieg ausgehungert und frisst jetzt für drei Generationen nach!\"  2. Der haut rein, als wär gerade Bombenalarm im Wirtshaus und das sein letzter Schweinsbraten!  3. Der schaut sein Essen an wie ein Goldgräber den letzten Nugget – und dann frisst er’s weg wie ein Schaufelbagger!"}]'::jsonb, ''),
  ('si-woa-so-giarich-noch-eam-dass-eam-fost-es-heemad-vom-leib-grissn-haett', 'Si woa so giarich noch eam, dass eam fost es Heemad vom Leib grissn hätt!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie war so gierig nach ihm, dass sie ihm fast das Hemd vom Leib gerissen hätt!', '[{"kategorie": "wörtlich", "text": "\"Sie war so heiß auf ihn, dass sie ihm fast das Hemd vom Leib gerissen hätt!\"  2. Sie war so verrückt nach ihm, dass sie ihm am liebsten die Kleider vom Leib gerissen hätte!  3. Die Gier in ihr war so stark, dass sie ihm das Hemd am liebsten mit den Zähnen runtergerissen hätt!"}]'::jsonb, ''),
  ('sei-ned-so-siarich', 'Sei ned so siarich!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Sei nicht so sierig!', '[{"kategorie": "wörtlich", "text": "\"Jetzt sei mal nicht so knausrig!\"  2. Tu mal nicht so geizig!  3. Komm, rück mal raus!"}]'::jsonb, ''),
  ('siarich-auf-wos-sei', 'siarich auf wos sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'sierig auf etwas sein', '[{"kategorie": "wörtlich", "text": "\"gierig auf etwas sein\""}, {"kategorie": "", "text": "versessen auf etwas sein"}, {"kategorie": "", "text": "wild auf etwas sein"}, {"kategorie": "", "text": "begierig auf etwas sein"}, {"kategorie": "", "text": "[[auf]] etwas spitzen"}]'::jsonb, ''),
  ('de-kotz-is-gaunz-siarich-aufs-roohe-fleisch', 'De Kotz is gaunz siarich aufs roohe Fleisch!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Die Katze ist ganz sierig aufs rohe Fleisch!', '[{"kategorie": "wörtlich", "text": "\"Die Katze giert nach rohem Fleisch!\"  2. Die Katze ist ganz wild auf rohes Fleisch!  3. Die Katze ist wie versessen auf rohes Fleisch!"}]'::jsonb, ''),
  ('des-schaud-echt-giarich-aus', 'Des schaud echt giarich aus!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Das schaut echt gierig aus!', '[{"kategorie": "wörtlich, Jugendsprache", "text": "Das sieht wirklich geil aus!  2. Das sieht echt krass aus!  3. Das sieht wirklich cool aus!"}]'::jsonb, ''),
