  ('abara-kadabara-jetzt-fress-ma-unsan-haawara', 'Abara, kadabara, jetzt fress ma unsan Haawara!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Abara, kadabara, jetzt fressen wir unseren Haberer!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Das Essen ist unser Freund, also muss es runter, abara, kadabara!\"  2. Abrakadabra, lasst uns den Fraß ratzfatz vertilgen!  3. Abrakadabra, auch schlechtes Essen muss runter in den Magen!"}]'::jsonb, ''),
  ('abara-kadabara-a-kiiwara-is-ka-haawara', 'Abara, kadabara, a Kiiwara is ka Haawara!', '', '', '', 'Wiener Gaunersprache', 'Abara, kadabra, ein Kieberer ist kein Haberer!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Abara Kadabara, ein Polizist ist kein Freund und Helfer!\" (Scherzreim als Antwort auf den offiziellen Polizeislogan: \"Die Polizei - den Freund und Helfer!\")  2. Mit Polizisten verbrüdert man sich nicht!  3. Polizisten sind deine Freunde nicht!"}]'::jsonb, ''),
