  ('de-hockn-is-schdumpf-i-muass-schleifn', 'De Hockn is schdumpf, I muass schleifn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die Hacke ist stumpf - ich muss sie schleifen!', '[{"kategorie": "wörtlich", "text": "\"Die Hacke ist nicht mehr scharf – ich muss sie schärfen!\"  2. Meine Hacke schneidet nicht mehr – Zeit, sie zu schleifen!  3. Mit der stumpfen Hacke komme ich nicht weiter – die braucht ''nen Schliff!"}]'::jsonb, ''),
  ('da-goodankaeula-woat-schoo-wia-miassn-de-hockn-bis-muang-duachziang', 'Da Goodankäula woat schoo - wia miassn de Hockn bis muang duachziang!', '', '', '', 'Wiener Gaunersprache', 'Der Gadernkeiler wartet schon – wir müssen die Hacken bis morgen durchziehen!', '[{"kategorie": "wörtlich", "text": "\"Der Schmuckhehler wartet schon – wir müssen den Job bis morgen durchziehen!\"  2. Der Hehler sitzt schon auf heißen Kohlen – wir müssen den Coup bis morgen abwickeln!  3. Der Schieber will nicht länger warten – wir machen das Ding heute Nacht!"}]'::jsonb, ''),
  ('ind-hockn-gee', 'ind Hockn gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'in die Hacken gehen', '[{"kategorie": "wörtlich", "text": "\"zur Arbeit gehen\", \"seiner beruflichen Tätigkeit nachgehen\", \"arbeiten gehen\", [[hackln gee]]"}, {"kategorie": "Gaunersprache", "text": "einen Job erledigen, ein Ding drehen, einen Coup landen"}, {"kategorie": "Gaunersprache", "text": "\"anschaffen gehen\", der Prostitution nachgehen, auf den Strich gehen"}]'::jsonb, 'I gee ind Hockn und mei Oide geed schoppn - rennd leiwaund bei uns!'),
